"""Read-only source review of the transported immutable StandardCurveModel packet."""
import hashlib,json,subprocess,time
from pathlib import Path
HERE=Path(__file__).resolve().parent;F=HERE/'frozen';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
manifest=json.loads((F/'manifest.json').read_text());assert all(sha(F/n)==x['sha256'] for n,x in manifest['files'].items())
prompt=f'''Review the frozen Windows proof packet at {F} read-only using Read/Glob/Grep only. Do not edit, run code or builds. Focus on the14 fresh maintained-source modules culminating ConcreteStandardCurveModel01.model and addition_image. Canonical dependencies are exact source hashes verified locally under canonical-dependencies; audited-source contains generated full-type/axiom print wrappers. Existing addition06's2modules17audits are inherited, not fresh. Review for mathematical defects, incomplete exceptional cases (identity,torsion,cross-zero,inverse,secant,tangent), denominator prerequisites, field/curve parameter assumptions, actual Mathlib Point operation correspondence and full Edwards solution coverage. Confirm model is actual Point group and addition is proved, without an assumed morphism/order/cardinality/native premise. Check what remains open: actual scalar trace, point order/cardinality, nativecodec/runtimegeneratoridentity, other Transfer and full Transfer. ConcreteStandardCurveModel uses DecidableEq F; assess whether this is a computational assumption or mathematical gap. Parent will independently reconstruct14auditedsources and reparse54existingtypes/standardaxioms, not rerunLean. Receipt/transport hash alone is not a proof. Inspect proof dependencies as needed; prior parameter/Point equivalence/subgroup prime scopes are already reviewed. Report actionable mathematical/scope defects with evidence, otherwise no defect within stated scope. Distinguish maintenance observations from mathematical blockers.'''
(HERE/'review-prompt.txt').write_text(prompt+'\n');start=time.monotonic()
cmd=['/Users/antoinecyr/.local/bin/claude','--model','claude-opus-5-5','--effort','high','--permission-mode','plan','--tools','Read,Glob,Grep','--strict-mcp-config','--no-session-persistence','--output-format','json','--print',prompt]
with (HERE/'opus55-review.json').open('w') as out,(HERE/'opus55-review.stderr').open('w') as err:r=subprocess.run(cmd,stdout=out,stderr=err,timeout=900)
review=json.loads((HERE/'opus55-review.json').read_text());assert r.returncode==0 and not review['is_error'] and 'claude-opus-5-5' in review['modelUsage']
assert all(sha(F/n)==x['sha256'] for n,x in manifest['files'].items());print(json.dumps({'review':'complete','model':list(review['modelUsage']),'seconds':time.monotonic()-start}))
